// Count existing entries per category
function countEntries(content, catName) {
  const startMarker = `D.${catName} = [`;
  const startIdx = content.indexOf(startMarker);
  if (startIdx === -1) return 0;
  const afterBracket = content.indexOf('[', startIdx) + 1;
  const chunk = content.slice(afterBracket, afterBracket + 50000);
  // Find closing ];
  let depth = 1;
  let endIdx = 0;
  for (let i = 0; i < chunk.length; i++) {
    if (chunk[i] === '[') depth++;
    else if (chunk[i] === ']') {
      depth--;
      if (depth === 0) { endIdx = i; break; }
    }
  }
  const arrayContent = chunk.slice(0, endIdx);
  const matches = arrayContent.match(/\{n:'/g);
  return matches ? matches.length : 0;
}

for (const [cat, entries] of Object.entries(inserts)) {
  const startMarker = `D.${cat} = [`;
  const startIdx = html.indexOf(startMarker);
  if (startIdx === -1) {
    console.error(`Category ${cat} not found`);
    continue;
  }
  const afterOpenBracket = html.indexOf('[', startIdx) + 1;
  const chunk = html.slice(afterOpenBracket, afterOpenBracket + 50000);
  let depth = 1;
  let endIdx = 0;
  for (let i = 0; i < chunk.length; i++) {
    if (chunk[i] === '[') depth++;
    else if (chunk[i] === ']') {
      depth--;
      if (depth === 0) { endIdx = i; break; }
    }
  }
  const arrayContent = chunk.slice(0, endIdx);
  const existingCount = (arrayContent.match(/\{n:'/g) || []).length;
  const currentTotal = afterOpenBracket + endIdx;

  if (existingCount < 50) {
    const insertIdx = currentTotal;
    let insertStr = '';
    for (let j = existingCount; j < 50 && j - existingCount < entries.length; j++) {
      const e = entries[j - existingCount];
      const la = typeof e.la === 'number' ? e.la : parseFloat(e.la);
      const ln = typeof e.ln === 'number' ? e.ln : parseFloat(e.ln);
      insertStr += `  {n:'${e.n}',la:${la},ln:${ln},sub:'${e.sub}',desc:'${e.desc}',fact:'${e.fact}'},`;
    }
    if (insertStr) {
      html = html.slice(0, insertIdx) + '\n' + insertStr + html.slice(insertIdx);
    }
    console.log(`${cat}: ${existingCount} → ${existingCount + entries.length} (added ${entries.length})`);
  }
}

fs.writeFileSync(filePath, html, 'utf8');
console.log('Done writing file');
